contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test takes an Order encoded as its parameters. We cannot pass complex structs directly
    // in the function signature for generality, so provide the key fields used by cancel(): maker and the rest packed.
    function run(address maker, bool isCall, bool isLong, address baseAsset, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce, address[] memory whitelist, address[] memory floorTokens, address[] memory erc20_tokens, uint256[] memory erc20_amounts, address[] memory erc721_tokens, uint256[] memory erc721_ids) public payable {
        // Build the Order struct in calldata for calling c.hashOrder and c.cancel / view of cancelledOrders.
        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;

        // Build ERC20Asset[] and ERC721Asset[] for the Order from the provided parallel arrays.
        if (erc20_tokens.length == erc20_amounts.length) {
            order.erc20Assets = new C.ERC20Asset[](erc20_tokens.length);
            for (uint i = 0; i < erc20_tokens.length; i++) {
                order.erc20Assets[i] = C.ERC20Asset(erc20_tokens[i], erc20_amounts[i]);
            }
        } else {
            // mismatch lengths: leave empty to keep the test inputs valid
            order.erc20Assets = new C.ERC20Asset[](0);
        }

        if (erc721_tokens.length == erc721_ids.length) {
            order.erc721Assets = new C.ERC721Asset[](erc721_tokens.length);
            for (uint i = 0; i < erc721_tokens.length; i++) {
                order.erc721Assets[i] = C.ERC721Asset(erc721_tokens[i], erc721_ids[i]);
            }
        } else {
            order.erc721Assets = new C.ERC721Asset[](0);
        }

        // Precondition: nothing about c's state; we only observe behaviour of cancel.
        // Call cancel as if this contract is the caller. The spec: cancel requires msg.sender == order.maker.
        // We will call cancel and capture whether it reverted.
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Compute orderHash via public hashOrder and then read cancelledOrders mapping via public getter.
        bytes32 h = c.hashOrder(order);
        bool observed = c.cancelledOrders(h);

        // Assert the general rule:
        // If this contract was the maker (maker == address(this)) then cancel must not revert and cancelledOrders[hash] must be true.
        // If this contract was not the maker then cancel must revert and cancelledOrders[hash] must be false (i.e., non-maker cannot cancel).
        // This ties observed state to caller equality for ALL inputs.
        assert( (maker == address(this) && !reverted && observed) || (maker != address(this) && reverted && !observed) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We keep inputs small: only fields needed to build an Order for cancel/hashOrder check.
    function run(address maker, address baseAsset, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce, address[] memory whitelist, address[] memory floorTokens) public payable {
        // Precondition: choose reasonable durations and expiration to avoid internal require failures elsewhere
        require(duration < 10_000 days, "duration too long");

        // Build minimal Order struct. Other asset arrays left empty via default.
        C.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        // Attempt to call cancel and record whether it reverted.
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe mapping value via public getter and order hash via public view.
        bytes32 h = c.hashOrder(order);
        bool observedCancelled = c.cancelledOrders(h);

        // Assert the intended invariant for ALL inputs: caller==maker <=> cancel succeeds and mapping true.
        assert( (maker == address(this) && !reverted && observedCancelled) || (maker != address(this) && reverted && !observedCancelled) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test fillOrder behavior for a simple long non-call order where premium transfer path is the 'isLong' branch.
    function run(address maker, address baseAsset, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce) public payable {
        // Preconditions to satisfy internal requires in fillOrder
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp, "order expired");
        require(baseAsset != address(0), "baseAsset zero");
        // Make order such that isLong == true and isCall == false to hit the branch where maker pays strike into contract later

        C.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = true;
        order.baseAsset = baseAsset;
        order.strike = 0;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        // Pre-observe unclaimedFees and maker allowance/state: only public getter available
        uint256 beforeFees = c.unclaimedFees(baseAsset);

        // Attempt to fill; record whether it reverted
        bool reverted;
        try c.fillOrder{value: 0}(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterFees = c.unclaimedFees(baseAsset);

        // General rule: If call did not revert and contract fee > 0, then afterFees == beforeFees + (premium*fee)/1000.
        // If call reverted then nothing is required; we assert the conditional implication.
        uint256 feeRate = c.fee();
        assert(reverted || feeRate == 0 || afterFees == beforeFees + (premium * feeRate) / 1000);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters: maker (who created the order), caller (who will call cancel), baseAsset and basic numeric fields
    function run(address maker, address caller, address baseAsset, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce) public payable {
        // Preconditions to make the Order valid for hashOrder and to satisfy some internal requires when other functions might be called.
        require(maker != address(0) && caller != address(0), "zero addr");
        require(duration < 10_000 days, "duration too long");
        require(expiration > block.timestamp + 1, "expiration must be in future");
        require(baseAsset != address(0), "baseAsset zero");

        // Build a minimal Order struct with arrays empty so hashOrder is well-defined
        C.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new C.ERC20Asset[](0);
        order.erc721Assets = new C.ERC721Asset[](0);

        // Observe cancelled status before
        bytes32 h = c.hashOrder(order);
        bool before = c.cancelledOrders(h);

        // Try to call cancel as 'caller' (not maker). To simulate call from 'caller', we require that the test contract forwards via call:
        // We cannot change msg.sender for c.cancel; instead we check the property by calling cancel from this contract only when this contract != maker.
        // So require that the provided caller is not the maker and that this contract is not the maker.
        require(caller != maker, "caller must differ from maker");
        require(address(this) != maker, "test contract must not be maker");

        // Execute cancel from this contract (which is not the maker). The rule we assert: cancel must revert and mapping stays false.
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.cancelledOrders(h);

        // GENERAL RULE: If msg.sender is not the order.maker (here address(this) != maker), then cancel must revert and the mapping remains false.
        assert(reverted && before == false && after == false);
    }

    receive() external payable {}
}

